define('ROOT_PATH',dirname(__DIR__));define('APP_PATH',ROOT_PATH.'/app');require APP_PATH.'/helpers.php';require APP_PATH.'/Core/Autoloader.php';Autoloader::register();$db=Database::connection();
if(in_array('--migrate',$argv,true)){foreach(array_filter(array_map('trim',explode(';',(string)file_get_contents(ROOT_PATH.'/database/migrations/20260822_project_file_version_changes.sql')))) as $sql)$db->exec($sql);}
