    if($otherProject!==$project){$obs->execute(['project'=>$otherProject,'file'=>null,'actor'=>$student,'body'=>'Observación de otro proyecto','status'=>'pending']);$otherProjectObservation=(int)$db->lastInsertId();}else{$otherProjectObservation=PHP_INT_MAX;}
